#!/usr/bin/env bash
# Phase2 version of runCMSDrivers_mc2024_BBbar_SIM.sh: the Geant4 simulation of the bbbar events in the
# Phase2 (HL-LHC) detector switched on stage by stage, in the spirit of the generator stages of
# runCMSDrivers_mc2024_BBbar_GEN.sh. Every stage is a step 2 (process SIM) generated by cmsDriver.py with
# the settings of the Run4D110 RelVal workflow of this release (geometry ExtendedRun4D110, era
# Phase2C17I13M9, GT auto:phase2_realistic_T33, beamspot DBrealisticHLLHC, 14 TeV), on the step 1 output
# of the full generator stage (GEN_Phase2/step1_GEN_ME_PS_MPI_Had_Decay_out.root by default: the GEN
# script with the Phase2 conditions and beamspot, since the vertex smearing happens in the GEN step),
# with the Geant4 physics restricted through --customise_commands:
#   Transport                 transportation only: no magnetic field, no decays, no electromagnetic and
#                             no hadronic physics (physics list JitJetSW/Journey JourneyTransportPhysics);
#                             the generator particles fly in straight lines through the detector
#   Transport_B               + magnetic field (UseMagneticField): charged particles bend
#   Transport_B_Decay         + decays in flight (G4DecayPhysics; FTFP_BERT_EMM with EMPhysics and
#                             HadPhysics off): pi, K, K0S, Lambda, mu ... decay, new particles appear
#   Transport_B_Decay_EM      + electromagnetic physics (EMPhysics): ionisation (energy loss, delta rays),
#                             multiple scattering, bremsstrahlung, pair production, Compton, photoelectric
#                             effect: electromagnetic showers, real energy deposits in the sensitive volumes
#   Transport_B_Decay_EM_Had  + hadronic physics (HadPhysics): nuclear interactions, hadronic showers;
#                             the full FTFP_BERT_EMM list, i.e. the standard SIM step of the main script
# Without electromagnetic physics nothing deposits energy, so the tracker records every sensor crossing
# as a hit with zero energy loss (TrackerSD.ZeroEnergyLoss) and the calorimeters record nothing; the
# crossing of the tracker / calorimeter boundary is kept on every SimTrack (CaloTrkProcessing) in all stages.
# Phase2 detector (D110): the inner and the outer tracker both write their PSimHits as
# TrackerHitsPixelBarrel/Endcap (no TIB/TID/TOB/TEC collections), the muon system has GEM but no ME0,
# the endcap calorimeters are the HGCal (HGCHitsEE, HGCHitsHEfront, HGCHitsHEback: silicon and
# scintillator cells, drawn as HGC EE / HSi / HSc by SimAnalyzer) and EcalHitsEE, EcalHitsES and the HE
# part of HcalHits do not exist; the MTD timing layers (FastTimerHitsBarrel/Endcap) are not drawn.
# For each stage it writes, in the output directory (default SIM_Phase2/ below the current directory):
#   step2_SIM_<stage>_cfg.py, step2_SIM_<stage>_cfg.driver.log       cmsDriver config and log
#   step2_SIM_<stage>_out.root, step2_SIM_<stage>_out.log            cmsRun output and log
#   simAnalyzer_<stage>_out.pdf, .root, .log                          eta-phi maps (GenPartAnalyzer + SimAnalyzer)
# The PDF holds per analysed event the generator-record pages of GenPartAnalyzer (GENSTAGES, default 5)
# followed by the five SimAnalyzer pages: primaries handed to Geant4, the primaries at the tracker /
# calorimeter boundary, the secondaries by creator process, the tracker and muon SimHits and the
# calorimeter SimHits per cell. The b and bbar are followed from the hard process to the energy deposits.
# Run from an initialized CMSSW environment.
#   EVENTS=10                             events per stage (default 1; -1 = all events of the input)
#   STAGES="Transport Transport_B"        subset of stages (default all five)
#   INPUT=GEN_Phase2/step1_GEN_ME_PS_MPI_Had_Decay_out.root  step 1 (GEN) input file; the default is generated
#                                         with runCMSDrivers_mc2024_BBbar_GEN.sh (stage ME_PS_MPI_Had_Decay,
#                                         EVENTS events, Phase2 conditions, era, geometry, beamspot and 14 TeV
#                                         through its CONDITIONS, ERA, GEOMETRY, BEAMSPOT and COMENERGY
#                                         variables) if it does not exist. INPUT=GEN/step1_GEN_ME_PS_MPI_Had_Decay_out.root
#                                         runs the Phase2 detector on the 2024 events of the 2024 scripts
#                                         (13.6 TeV, Run 3 beamspot) for a one-to-one comparison
#   BEAMSPOT=DBrealisticHLLHC             vertex smearing (default DBrealisticHLLHC, as the Run4 RelVal); used in
#                                         the GEN step of the generated input and passed to the SIM step
#   OUTDIR=SIM_Phase2                     output directory (default SIM_Phase2)
#   RUN=0                                 only generate the configs, do not run cmsRun
#   REUSE=1                               keep existing step2_SIM_<stage>_out.root files, only (re)run the analyzers
#   ANALYZE=0                             skip the analyzer step
#   ANALYZE_EVENTS=1                      events drawn per stage by the analyzers (default 1)
#   GENSTAGES=5                           GenPartAnalyzer pages before the SIM pages of every event (0: none)
#   DUMP, DUMP_MAX, DUMP_SUB, DUMP_G4_THRESHOLD  as in runCMSDrivers_mc2024_BBbar.sh (SIM step)
set -euo pipefail

events=${EVENTS:-1}
stages=${STAGES:-"Transport Transport_B Transport_B_Decay Transport_B_Decay_EM Transport_B_Decay_EM_Had"}
input=${INPUT:-GEN_Phase2/step1_GEN_ME_PS_MPI_Had_Decay_out.root}
beamspot=${BEAMSPOT:-DBrealisticHLLHC}
outdir=${OUTDIR:-SIM_Phase2}
run=${RUN:-1}
reuse=${REUSE:-0}
analyze=${ANALYZE:-1}
analyze_events=${ANALYZE_EVENTS:-1}
gen_stages=${GENSTAGES:-5}
# Run4D110 RelVal workflow of CMSSW_15_0_5 (Configuration/PyReleaseValidation upgradeWorkflowComponents.py)
conditions=auto:phase2_realistic_T33
era=Phase2C17I13M9
geometry=ExtendedRun4D110
com_energy=14000.0
dump=${DUMP:-0}
dump_max=${DUMP_MAX:--1}
dump_sub=${DUMP_SUB:--1}
dump_g4_threshold=${DUMP_G4_THRESHOLD:-1.0}
dump_customise="from JitJetSW.Journey.jitJet_cff import customiseJitJet; process = customiseJitJet(process, level=${dump}, maxElements=${dump_max}, maxSub=${dump_sub}, g4Threshold=${dump_g4_threshold})"

if [[ ${CMSSW_VERSION:-} != CMSSW_15_0_5 ]]; then
  echo "Initialize CMSSW_15_0_5 with 'eval \"\$(scram runtime -sh)\"' first." >&2
  exit 1
fi

journey=$CMSSW_BASE/src/JitJetSW/Journey
analyzer_cfg=$journey/test/simAnalyzer_cfg.py
gen_script=$journey/test/runCMSDrivers_mc2024_BBbar_GEN.sh
# The simulation "biglib" of the release (biglib/pluginSimulation.so) carries its own statically linked,
# hidden copy of Geant4, while a physics list built in this package links the shared libG4run.so; mixing
# the two crashes in G4VModularPhysicsList::RegisterPhysics. The SIM step is therefore run with the biglib
# directories removed from the library path, so that cmsRun takes the ordinary shared-library build of the
# simulation (same code, same Geant4) for every stage.
sim_ld_library_path=$(echo "$LD_LIBRARY_PATH" | tr ':' '\n' | grep -v '/biglib/' | paste -sd:)

# Geant4 switches per stage (B field, decays, EM physics, hadronic physics) and the stage number
stage_switches() {
  case $1 in
    Transport)                echo off off off off 1 ;;
    Transport_B)              echo on  off off off 2 ;;
    Transport_B_Decay)        echo on  on  off off 3 ;;
    Transport_B_Decay_EM)     echo on  on  on  off 4 ;;
    Transport_B_Decay_EM_Had) echo on  on  on  on  5 ;;
    *) echo "Unknown stage '$1' (use Transport, Transport_B, Transport_B_Decay, Transport_B_Decay_EM, Transport_B_Decay_EM_Had)" >&2; exit 1 ;;
  esac
}

py_bool() { [[ $1 == on ]] && echo True || echo False; }

run_stage() {
  local stage=$1 bfield decay em had num
  read -r bfield decay em had num < <(stage_switches "$stage")
  local config="step2_SIM_${stage}_cfg.py"
  local output="step2_SIM_${stage}_out.root"
  local log="step2_SIM_${stage}_out.log"
  local args=(step2 --filein "file:$input" --conditions "$conditions" --era "$era" --geometry "$geometry"
              -n "$events" -s SIM --datatier GEN-SIM --eventcontent FEVTDEBUG --beamspot "$beamspot"
              --fileout "file:$output" --python_filename "$config" --no_exec)
  local -a customise=("process.g4SimHits.UseMagneticField = cms.bool($(py_bool "$bfield"))")
  if [[ $decay == off ]]; then
    # transportation only; FTFP_BERT_EMM always registers G4DecayPhysics
    customise+=("process.g4SimHits.Physics.type = cms.string('SimG4Core/Physics/JourneyTransportPhysics')")
  else
    customise+=("process.g4SimHits.Physics.EMPhysics = cms.untracked.bool($(py_bool "$em"))"
                "process.g4SimHits.Physics.HadPhysics = cms.untracked.bool($(py_bool "$had"))")
  fi
  if [[ $em == off ]]; then
    # no EM processes: no multiple scattering to couple to the transportation, no gamma general process,
    # and no energy loss, so the tracker records the sensor crossings as hits with eLoss = 0
    customise+=("process.g4SimHits.Physics.G4TransportWithMSC = cms.int32(0)"
                "process.g4SimHits.Physics.G4GammaGeneralProcess = cms.bool(False)"
                "process.g4SimHits.TrackerSD.ZeroEnergyLoss = cms.bool(True)")
  fi
  if (( dump > 0 )); then
    customise+=("$dump_customise")
  fi
  # cmsDriver splits --customise_commands on a literal backslash-n
  local joined=${customise[0]} c
  for c in "${customise[@]:1}"; do joined+='\n'"$c"; done
  args+=(--customise_commands "$joined")

  echo "Stage $stage: B=$bfield Decay=$decay EM=$em Had=$had (beamspot $beamspot, input $input)"
  if (( reuse )) && [[ -s $output ]]; then
    echo "  Reusing $output"
  else
    cmsDriver.py "${args[@]}" > "${config%.py}.driver.log" 2>&1 || {
      cat "${config%.py}.driver.log" >&2; exit 1;
    }
    echo "  Generated $config"
    (( run )) || return 0
    LD_LIBRARY_PATH=$sim_ld_library_path cmsRun "$config" > "$log" 2>&1 || { tail -80 "$log" >&2; exit 1; }
    [[ -s $output ]] || { echo "No output produced: $output" >&2; exit 1; }
    echo "  Completed $output"
  fi

  (( analyze )) || return 0

  local aprefix="simAnalyzer_${stage}_out"
  local input_stage=$(basename "$input" _out.root); input_stage=${input_stage#step1_GEN_}
  local label="sample $stage|B field $bfield, Decay $decay|EM $em, Had $had|input $input_stage"   # '|' = new line
  cmsRun "$analyzer_cfg" inputFiles="file:$output" outputFile="$aprefix.root" maxEvents="$analyze_events" \
    simStage="$num" genStages="$gen_stages" globalTag="$conditions" era="$era" geometry="$geometry" pdfFile="$aprefix.pdf" \
    sampleLabel="$label" > "$aprefix.log" 2>&1 || { tail -40 "$aprefix.log" >&2; exit 1; }
  [[ -s $aprefix.pdf ]] || { echo "No PDF produced: $aprefix.pdf" >&2; exit 1; }
  echo "  Completed $aprefix.pdf ($gen_stages generator-stage page(s) + 5 SIM pages per event)"
}

# JitJetSW/Journey plugins: the JourneyTransportPhysics physics list (Transport stages), GenPartAnalyzer
# and SimAnalyzer (ANALYZE=1) and the dump customisation (DUMP>0). Rebuild when the plugin library is
# missing or older than the sources.
[[ -d $journey ]] || { echo "Missing package JitJetSW/Journey" >&2; exit 1; }
plugin_lib=$CMSSW_BASE/lib/$SCRAM_ARCH/pluginJitJetSWJourneyAuto.so
if [[ ! -s $plugin_lib ]] || [[ -n $(find "$journey/plugins" -name '*.cc' -newer "$plugin_lib") ]] ||
   { (( dump > 0 )) && ! python3 -c 'import JitJetSW.Journey.jitJet_cff' 2>/dev/null; }; then
  echo "Building JitJetSW/Journey"
  # full build (not only the package) so that the edm plugin cache is refreshed
  (cd "$CMSSW_BASE/src" && scram b -j 4 > jitjet_build.log 2>&1) || { cat "$CMSSW_BASE/src/jitjet_build.log" >&2; exit 1; }
fi

# step 1 input: the full generator stage of the GEN script with the Phase2 conditions, era, geometry,
# beamspot and com energy, generated here if the default is missing
if [[ ! -s $input ]] && ! (( reuse )); then
  if [[ -n ${INPUT:-} ]] || (( ! run )); then
    echo "Missing input: $input" >&2; exit 1
  fi
  echo "Input $input missing: running runCMSDrivers_mc2024_BBbar_GEN.sh (stage ME_PS_MPI_Had_Decay, Phase2 settings) first"
  gen_env=(STAGES=ME_PS_MPI_Had_Decay ANALYZE=0 OUTDIR="$(dirname "$input")"
           CONDITIONS="$conditions" ERA="$era" GEOMETRY="$geometry" BEAMSPOT="$beamspot" COMENERGY="$com_energy")
  (( events > 0 )) && gen_env+=(EVENTS="$events")
  env "${gen_env[@]}" "$gen_script"
  [[ -s $input ]] || { echo "GEN script did not produce $input" >&2; exit 1; }
fi
[[ -s $input ]] && input=$(readlink -f "$input")   # with REUSE=1 the input is only needed for stages without output

mkdir -p "$outdir"
cd "$outdir"
echo "Writing to $PWD"
for stage in $stages; do
  run_stage "$stage"
done
